// Build one HTML table from all plant rows.
const rows = $input.all().map(i => i.json);
const tr = rows.map(r => `<tr><td>${r.PlantName}</td><td align=right>${r.OutputBoxes}</td><td align=right>${r.DefectBoxes}</td><td align=right>${r.DefectPct}%</td></tr>`).join('');
const worst = rows.reduce((a, b) => (Number(b.DefectPct) > Number(a.DefectPct) ? b : a), rows[0] || {});
return [{ json: {
  subject: `Daily production: ${rows.reduce((s, r) => s + r.OutputBoxes, 0)} boxes, highest defect ${worst.PlantName} ${worst.DefectPct}%`,
  html: `<table border=1 cellpadding=4><tr><th>Plant</th><th>Output</th><th>Defects</th><th>Defect %</th></tr>${tr}</table>`
} }];
